import{_ as a,o as i,c as t,a5 as h}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Phần 3.5 còn lại — giai đoạn 1: chốt nghiệp vụ","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/remaining-work/spec.md","filePath":"feature/media-package-campaign/remaining-work/spec.md"}'),c={name:"feature/media-package-campaign/remaining-work/spec.md"};function e(g,n,o,r,l,u){return i(),t("div",null,[...n[0]||(n[0]=[h('<h1 id="phan-3-5-con-lai-—-giai-đoan-1-chot-nghiep-vu" tabindex="-1">Phần 3.5 còn lại — giai đoạn 1: chốt nghiệp vụ <a class="header-anchor" href="#phan-3-5-con-lai-—-giai-đoan-1-chot-nghiep-vu" aria-label="Permalink to &quot;Phần 3.5 còn lại — giai đoạn 1: chốt nghiệp vụ&quot;">​</a></h1><p>Ngày: 2026-10-13. Giai đoạn này chỉ chỉnh tài liệu, không code, chạy migration hoặc sửa dữ liệu. Không phải <code>phase-1-design</code> của đợt Campaign trước.</p><p>&gt; <strong>Quyết định sau này 2026-10-14 thay thế các dòng lịch sử bên dưới về campaignId=null và xử lý Request sau hoàn thành:</strong> xem ../campaign-closure/spec.md. Task Request mới gắn Campaign; mọi Task chưa kết thúc và Request IN_PROGRESS chặn hoàn thành. PENDING tự hủy sau hoàn thành thành công. Manager có bulk cancel Task với lý do chung, không xóa lịch sử.</p><h2 id="nguon-va-quyet-đinh-đa-đuoc-nguoi-dung-xac-nhan" tabindex="-1">Nguồn và quyết định đã được người dùng xác nhận <a class="header-anchor" href="#nguon-va-quyet-đinh-đa-đuoc-nguoi-dung-xac-nhan" aria-label="Permalink to &quot;Nguồn và quyết định đã được người dùng xác nhận&quot;">​</a></h2><ul><li>DA-951 / E50-10 / FR 3.5.7–3.5.10: Client tạo yêu cầu bổ sung chỉ khi Campaign IN_PROGRESS và deployment SUCCEEDED; Campaign COMPLETED không cho tạo mới. Request đã có tiếp tục được xử lý theo trạng thái hiện tại, không tự hủy/khóa khi Campaign hoàn thành. Task sinh ra vẫn có <code>campaignId=null</code>.</li><li>Client sửa tiêu đề, mô tả, loại và hạn hoàn thành khi <code>PENDING</code>; người tạo được hủy bằng <code>CANCELLED</code>, không hard delete.</li><li>Manager bấm <strong>Tiếp nhận yêu cầu</strong>: <code>PENDING -&gt; IN_PROGRESS</code> (<strong>Đang xem xét</strong>). Xem trang không kích hoạt chuyển trạng thái. Sau tiếp nhận, Client không được sửa/hủy.</li><li>Manager chấp nhận/từ chối từ <code>IN_PROGRESS</code>. Chấp nhận sinh đúng một Task BACKLOG; trạng thái cuối không mở lại.</li><li>DA-943: bỏ scheduled reminder chọn Package; giữ gate Package hiện có. Không thêm scheduler/notification cho yêu cầu cũ này.</li><li>DA-949: đối tác chưa từng được Campaign sử dụng được xóa; đối tác đã được sử dụng chỉ ngừng sử dụng. Không cho gán mới nhưng các Campaign đang liên kết vẫn xem/cập nhật hợp tác.</li><li>DA-950: không làm lại module hợp tác; tích hợp cờ khả dụng và kiểm thử hồi quy.</li><li>Chỉ Owner quản lý danh bạ cấp Agency; Manager/Creator chỉ chọn/gán đối tác theo quyền Workspace DA-950. Người dùng đã chốt cả ba câu hỏi bổ sung trong phiên 2026-10-13.</li></ul><h2 id="ranh-gioi" tabindex="-1">Ranh giới <a class="header-anchor" href="#ranh-gioi" aria-label="Permalink to &quot;Ranh giới&quot;">​</a></h2><p>Giữ một Campaign/Workspace, Campaign đã duyệt bất biến, Task Mongo V2. Không init Atlas, tạo account mới, sửa module editor/social/AI của thành viên khác hoặc xây billing/booking. EVENT_PLAN/PRESS_RECOMMENDATION tiếp tục thuộc luồng Task đã chốt; Request giữ ba loại POST/LIVESTREAM/SURVEY theo spec hiện hành. Giới hạn đề xuất Client của Package hiện có không đổi.</p><h2 id="cau-hoi-đa-chot-—-2026-10-13" tabindex="-1">Câu hỏi đã chốt — 2026-10-13 <a class="header-anchor" href="#cau-hoi-đa-chot-—-2026-10-13" aria-label="Permalink to &quot;Câu hỏi đã chốt — 2026-10-13&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Quyết định</th></tr></thead><tbody><tr><td>Q1</td><td>Chỉ tạo mới khi Campaign IN_PROGRESS, deployment SUCCEEDED; COMPLETED không tạo mới.</td></tr><tr><td>Q2</td><td>Chỉ Owner quản lý danh bạ; Manager/Creator chọn/gán theo quyền DA-950.</td></tr><tr><td>Q3</td><td>Request đã có tiếp tục được xử lý sau khi Campaign hoàn thành; không tự hủy/đổi trạng thái.</td></tr></tbody></table><p>Các quyết định ở đây là xác nhận trong phiên làm việc; khi cập nhật BA dùng chung cần người dùng/lead thông báo team theo team guide. Không xem nhánh docs là thay thế việc review chung.</p><h2 id="hop-đong-va-tieu-chi-hoan-tat" tabindex="-1">Hợp đồng và tiêu chí hoàn tất <a class="header-anchor" href="#hop-đong-va-tieu-chi-hoan-tat" aria-label="Permalink to &quot;Hợp đồng và tiêu chí hoàn tất&quot;">​</a></h2><ul><li>Các spec FR 3.5.7–3.5.10 và <a href="./../partner-directory/spec.html">partner-directory/spec.md</a> là nguồn hành vi chi tiết; master-plan phải không mâu thuẫn với chúng.</li><li>UI Request dùng trạng thái yêu cầu riêng, không dùng SUBMITTED/ASSIGNED/PENDING_REVIEW của mock cũ. Task assignment/approval không thuộc DA-951.</li><li>Mọi UI mới dùng parallel vi/en và semantic light/dark; không nâng cấp lại toàn bộ UI chung.</li><li>Tài liệu đủ bốn file, nêu migration/preflight, rollback, chống trùng, test quyền/concurrency và checkpoint. Không còn câu hỏi BA chặn giai đoạn 2; mapping dữ liệu legacy phải inventory/review riêng trước migrate.</li></ul>',12)])])}const s=a(c,[["render",e]]);export{p as __pageData,s as default};
